from collections import Counter
from math import ceil, floor, gcd
for _ in range(int(input())):
	n = int(input())
	a = list(Counter([int(x) for x in input().strip().split()]).values())
	if len(a) == 1:
		print(ceil(a[0] / 2))
	else:
		a.sort()
		print(max(ceil(a[-1] / 2), a[-2]))
